#!/bin/bash
# c.sh '<js>'  : run in the driver with helpers: jp(name) -> both jpgs + pair; seed(file); nav(name, params)
S=/tmp/claude-0/-home-user/f9db4640-b55f-52a1-be6c-75264610aefd/scratchpad/loop/w
PRE='const S="'$S'";
const jp = async (name, which="both") => { for (const app of which==="both"?["packed","next"]:[which]) await (app==="packed"?P:N).screenshot({path:`${S}/s/${name}-${app}.jpg`,type:"jpeg",quality:72}); return name; };
const seed = async (file, phaseKv) => { const sv = JSON.parse(fs.readFileSync(`${S}/${file}`,"utf8")); await P.goto(urls.packed+"/404.html",{waitUntil:"load"}); await P.evaluate((kv)=>{localStorage.clear(); for (const [k,v] of Object.entries(kv)) localStorage.setItem(k,v);}, {...sv.packed, ...(phaseKv||{})}); await P.goto(urls.packed+"/",{waitUntil:"load"}); await N.goto(urls.next+"/",{waitUntil:"load"}); await N.evaluate((kv)=>{localStorage.clear(); for (const [k,v] of Object.entries(kv)) localStorage.setItem(k,v);}, sv.next); await N.goto(urls.next+"/",{waitUntil:"load"}); await wait(4000); return "seeded"; };
const nav = async (name, params) => { await N.evaluate(([n,p])=>window.__kibNav.go(n,p),[name,params]); await wait(1200); return "nav"; };

const leafs = (p) => p.evaluate(() => { const out=[]; const w=document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT); let n; while((n=w.nextNode())){ const t=n.textContent.replace(/\s+/g," ").trim(); if(!t) continue; const e=n.parentElement; const cs=getComputedStyle(e); if(cs.visibility==="hidden"||cs.display==="none"||+cs.opacity===0) continue; const rg=document.createRange(); rg.selectNodeContents(n); const r=rg.getBoundingClientRect(); if(r.width<1||r.height<1||r.bottom<0||r.top>innerHeight||r.right<0||r.left>innerWidth) continue; let o=1; for(let a=e;a;a=a.parentElement){ const c=getComputedStyle(a); o*=+c.opacity; if(c.visibility==="hidden") {o=0;break;} } if(o<0.05) continue; { const el=document.elementFromPoint(Math.min(innerWidth-1,Math.max(0,r.left+r.width/2)),Math.min(innerHeight-1,Math.max(0,r.top+r.height/2))); if(el && !(e.contains(el)||el.contains(e))) continue; } out.push({t:(cs.textTransform==="uppercase"?t.toUpperCase():t), x:Math.round(r.left), y:Math.round(r.top), w:Math.round(r.width), h:Math.round(r.height), fs:+parseFloat(cs.fontSize).toFixed(1), fw:cs.fontWeight, c:cs.color.replace(/\s/g,""), ff:cs.fontFamily.split(",")[0].replace(/["\x27]/g,"").slice(0,14), ls:cs.letterSpacing==="normal"?0:+parseFloat(cs.letterSpacing).toFixed(1)}); } return out; });

const box = (p, txt, up=5) => p.evaluate(([txt,up]) => { const w=document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT); let n; while((n=w.nextNode())){ if(n.textContent.trim()===txt){ const r0=n.parentElement.getBoundingClientRect(); if(r0.width<1||r0.bottom<0||r0.top>innerHeight) continue; const out=[]; let e=n.parentElement; for(let i=0;i<up&&e&&e!==document.body;i++,e=e.parentElement){ const r=e.getBoundingClientRect(), c=getComputedStyle(e); out.push(`${Math.round(r.x)},${Math.round(r.y)} ${Math.round(r.width)}x${Math.round(r.height)} pad ${c.padding} gap ${c.gap} r ${c.borderRadius} bg ${c.backgroundColor==="rgba(0, 0, 0, 0)"?"-":c.backgroundColor} ${c.backgroundImage!=="none"?"img "+c.backgroundImage.slice(0,110):""} ${c.boxShadow!=="none"?"sh "+c.boxShadow.slice(0,150):""} ${c.borderTopWidth!=="0px"?"bd "+c.borderTopWidth+" "+c.borderTopColor:""} lh ${c.lineHeight}`); } return out.join("\n"); } } return "not found"; }, [txt,up]);
const boxes = async (txt, up=5) => "PACKED\n"+await box(P,txt,up)+"\nKIB\n"+await box(N,txt,up);

const go = async (file) => { await seed(file); await click(N,/CONTINUE/); await wait(2500); return "in"; };
const both = async (re, o) => { const r=[]; for (const p of [P,N]) r.push(await click(p,re,o).catch(e=>"FAIL "+(p===P?"packed":"kib"))); return r.join(","); };
const diff = async (max=45) => { const a=await leafs(P), b=await leafs(N); const used=new Set(); const out=[]; const sig={}; const push=(k,line)=>{ if(sig[k]){sig[k].n++; return;} sig[k]={n:1,i:out.length}; out.push(line); }; const body=(f)=>/KRoboto|Roboto|apple|System|sans/.test(f); for(const x of a){ let best=-1,bd=1e9; b.forEach((y,i)=>{ if(used.has(i)||y.t!==x.t) return; const d=Math.abs(y.x-x.x)+Math.abs(y.y-x.y); if(d<bd){bd=d;best=i;} }); if(best<0){ out.push(`ONLY PACKED "${x.t.slice(0,40)}" @${x.x},${x.y} ${x.w}x${x.h} fs${x.fs} fw${x.fw} ${x.c} ${x.ff}`); continue; } used.add(best); const y=b[best]; const ds=[]; const ks=[]; if(Math.abs(y.x-x.x)>2||Math.abs(y.y-x.y)>2){ ds.push(`pos ${x.x},${x.y}->${y.x},${y.y}`); ks.push("pos"+(Math.abs(y.x-x.x)>2?"x"+(y.x-x.x):"")); } if(Math.abs(y.fs-x.fs)>0.4){ ds.push(`fs ${x.fs}->${y.fs}`); ks.push(ds[ds.length-1]); } if(Math.abs(y.w-x.w)>Math.max(3,x.w*0.06)&&Math.abs(y.fs-x.fs)<=0.4){ ds.push(`w ${x.w}->${y.w}`); ks.push("w"); } if(Math.abs((+y.fw)-(+x.fw))>=200 && body(x.ff)){ ds.push(`fw ${x.fw}->${y.fw}`); ks.push(ds[ds.length-1]); } if(y.c!==x.c){ ds.push(`col ${x.c}->${y.c}`); ks.push(ds[ds.length-1]); } if(body(x.ff)!==body(y.ff)){ ds.push(`font ${x.ff}->${y.ff}`); ks.push("font"); } if(Math.abs(x.ls-y.ls)>0.3){ ds.push(`ls ${x.ls}->${y.ls}`); ks.push(ds[ds.length-1]); } if(ds.length) push(ks.join("|"), `"${x.t.slice(0,28)}": ${ds.join("; ")}`); } b.forEach((y,i)=>{ if(!used.has(i)) out.push(`ONLY KIB "${y.t.slice(0,40)}" @${y.x},${y.y} ${y.w}x${y.h} fs${y.fs} fw${y.fw} ${y.c} ${y.ff}`); }); for(const k in sig) if(sig[k].n>1) out[sig[k].i]+=`   (x${sig[k].n})`; return out.slice(0,max).join("\n") || "NO TEXT DIFFS"; };
'
cd /home/user/Tierlist/.claude/worktrees/agent-a5efa660944d44ff7 && PT_PORT=${PT_PORT:-7801} node phone/tools/playtest/cmd.mjs "$PRE $1"
